import express from "express";
import {Pool} from "pg";
const app=express(); const db=new Pool();
app.get("/items", async (req,res)=>{
const name=req.query.name; return db.query(`SELECT name FROM items WHERE name = '${name}'`);
});

import express from "express";
import {Pool} from "pg";
const app=express(); const db=new Pool();
app.get("/items", async (req,res)=>{
const name=req.query.name; return db.query("SELECT name FROM items WHERE name=$1",[name]);
});

function wrap(x){return "SELECT name FROM items WHERE name = '"+x+"'";}
import express from "express";
import {Pool} from "pg";
const app=express(); const db=new Pool();
app.get("/items", async (req,res)=>{
return db.query(wrap(req.query.name));
});

