import fastify from "fastify";
import {PrismaClient} from "@prisma/client";
const app=fastify(); const db=new PrismaClient();
app.get("/items", async (req,res)=>{
const tenantId=req.body.tenantId; return db.item.findMany({where:{tenantId}});
});

import fastify from "fastify";
import {PrismaClient} from "@prisma/client";
const app=fastify(); const db=new PrismaClient();
app.get("/items", async (req,res)=>{
const ownerId=req.user.id; return db.item.findFirst({where:{id:req.params.id,ownerId}});
});

import fastify from "fastify";
import {PrismaClient} from "@prisma/client";
const app=fastify(); const db=new PrismaClient();
app.get("/items", async (req,res)=>{
const id=req.params.id; return db.item.update({where:{id},data:{name:req.body.name}});
});

import fastify from "fastify";
import {PrismaClient} from "@prisma/client";
const app=fastify(); const db=new PrismaClient();
app.get("/items", async (req,res)=>{
return db.item.count();
});

import fastify from "fastify";
import {PrismaClient} from "@prisma/client";
const app=fastify(); const db=new PrismaClient();
app.get("/items", async (req,res)=>{
return db.item.findMany({where:{OR:[{id:req.params.id},{tenantId:req.user.tenantId}]}});
});
